const stockNameCache = {};
const searchInstrumentsCache = {};

export function searchInstruments(query) {
  if (!query || query.length < 2) return [];

  // Use cache if available
  if (searchInstrumentsCache[query]) {
    return searchInstrumentsCache[query];
  }

  const lowerQuery = query.toLowerCase();

  const results = mapData
    .filter(
      (instrument) =>
        instrument.name.toLowerCase().includes(lowerQuery) ||
        instrument.tradingsymbol.toLowerCase().includes(lowerQuery)
    )
    .map((result) => ({
      tsym: result.tradingsymbol,
      token: result.instrument_token,
      exch: result.segment,
    }));

  // Store in cache
  searchInstrumentsCache[query] = results;
  return results;
}

export function searchStockName(instrument) {
  if (stockNameCache[instrument]) {
    return stockNameCache[instrument].tradingsymbol || "";
  }
  try {
    const name = mapData.find(
      (item) => item.instrument_token === instrument.toString()
    );
    if (name && name.tradingsymbol) {
      stockNameCache[instrument] = name;
      return name.tradingsymbol;
    }
    return "";
  } catch (error) {
    console.error("Error in searchStockName:", error);
    return "";
  }
}


